/** One bounded retry only for explicitly classified, read-only browsing GETs. */
const SAFE_GET_PREFIXES = [
  '/api/v1/nodes/', '/api/v1/search', '/api/v1/changes',
  '/api/v1/media/items', '/api/v1/media/facets', '/api/v1/media/albums',
  '/api/v1/file-favorites', '/api/v1/file-recent', '/api/v1/file-tags',
  '/api/v1/file-saved-searches', '/api/v1/file-quick-access',
] as const

function isReadEndpoint(path: string): boolean {
  // The path must be generated by our API adapter, never an untrusted full URL.
  if (!path.startsWith('/api/v1/') || path.includes('#')) return false
  const pathname = path.split('?', 1)[0]
  return SAFE_GET_PREFIXES.some(prefix => prefix.endsWith('/')
    ? pathname.startsWith(prefix)
    : pathname === prefix || pathname.startsWith(prefix + '/'))
}

export function xDrivePwaRetryableRead(path: string, init: RequestInit): boolean {
  return (init.method ?? 'GET').toUpperCase() === 'GET' && init.body == null && isReadEndpoint(path)
}

function retryDelay(response: Response): number | null {
  if (response.status !== 429 && response.status !== 503) return null
  const header = response.headers.get('Retry-After')?.trim()
  if (!header) return response.status === 429 ? 500 : 300
  // Respect Retry-After, including RFC HTTP-date. Never convert a long server
  // cooldown into an early retry; return the response for the UI instead.
  const seconds = Number(header)
  const value = Number.isFinite(seconds) && seconds >= 0
    ? seconds * 1000
    : Date.parse(header) - Date.now()
  if (!Number.isFinite(value)) return null
  return value <= 1200 ? Math.max(0, Math.ceil(value)) : null
}

function abortedError(): DOMException { return new DOMException('Request cancelled', 'AbortError') }

function foreground(signal?: AbortSignal | null): boolean {
  return !signal?.aborted && (typeof document === 'undefined' || document.visibilityState !== 'hidden')
}
function delayBeforeRetry(delayMs: number, signal?: AbortSignal | null): Promise<void> {
  if (signal?.aborted) return Promise.reject(abortedError())
  return new Promise<void>((resolve, reject) => {
    const cleanup = () => { clearTimeout(timer); signal?.removeEventListener('abort', onAbort) }
    const onAbort = () => { cleanup(); reject(abortedError()) }
    const timer = setTimeout(() => { cleanup(); resolve() }, delayMs)
    signal?.addEventListener('abort', onAbort, { once: true })
    if (signal?.aborted) onAbort()
  })
}

export async function xDriveFetchPwaSafeRead(
  url: string, path: string, init: RequestInit, send: typeof fetch = fetch,
): Promise<Response> {
  if (init.signal?.aborted) throw abortedError()
  const eligible = xDrivePwaRetryableRead(path, init)
  let first: Response
  try {
    first = await send(url, init)
  } catch (error) {
    if (!eligible || !(error instanceof TypeError) || !foreground(init.signal)) throw error
    await delayBeforeRetry(300, init.signal)
    if (!foreground(init.signal)) throw abortedError()
    // The second network attempt is final, including if it fails.
    return send(url, init)
  }
  if (!eligible || !foreground(init.signal)) return first
  const waitMs = retryDelay(first)
  if (waitMs === null) return first
  await delayBeforeRetry(waitMs, init.signal)
  if (!foreground(init.signal)) throw abortedError()
  return send(url, init)
}
